window.BANK = [{"id":"0001-que-resuelve-una-base-de-datos#1","lesson":"0001-que-resuelve-una-base-de-datos","block":"fund","q":"Un sensor registra <code>38.4</code> cada minuto durante un año, en un archivo. ¿Eso es información?","options":["No, son datos sin contexto suficiente","Sí, hay volumen y frecuencia altos"],"answer":0,"why":"Son datos: hechos registrados, sin el contexto que permita decidir. Falta saber qué mide, de quién, en qué unidad y en qué momento. Y fijate que el volumen no ayudó en nada — medio millón de mediciones sin contexto siguen sin ser información."},{"id":"0001-que-resuelve-una-base-de-datos#2","lesson":"0001-que-resuelve-una-base-de-datos","block":"fund","q":"Guardás en una carpeta todas las fotos, facturas y PDFs que fuiste juntando en cinco años. ¿Es una base de datos según Elmasri?","options":["No: le falta coherencia lógica","Sí: es una colección guardada"],"answer":0,"why":"Falla la segunda propiedad: la coherencia lógica. Elmasri es explícito — no es correcto denominar base de datos a un surtido aleatorio de datos. Tampoco hay un propósito específico ni un público previsto."},{"id":"0002-el-dbms#1","lesson":"0002-el-dbms","block":"fund","q":"¿Qué guarda el catálogo del DBMS?","options":["La descripción de la base, no sus datos","Los datos de la base, ya indexados","El registro de las operaciones hechas"],"answer":0,"why":"Exacto: metadatos. La descripción de la estructura — tablas, columnas, tipos, restricciones — no los datos en sí. Es lo que permite que un DBMS de propósito general trabaje con cualquier base sin haber sido escrito para ella."},{"id":"0002-el-dbms#2","lesson":"0002-el-dbms","block":"fund","q":"Un cajero de banco cobra una cuota mientras, en la misma sucursal, otro cajero cobra otra. ¿Qué función del DBMS está en juego?","options":["Compartición entre usuarios simultáneos","Manipulación de los datos guardados","Construcción de la base sobre disco"],"answer":0,"why":"Compartición: varios usuarios y programas accediendo simultáneamente. Es la función que obliga a todo el aparato de transacciones y bloqueos de la Unidad 6. Sin ella, un DBMS sería un archivo con mejores modales."},{"id":"0003-tres-niveles#1","lesson":"0003-tres-niveles","block":"fund","q":"El DBA crea un índice sobre <code>Estudiante.Año</code> para acelerar un reporte. ¿Qué esquema cambió?","options":["El interno, sin tocar el conceptual","El conceptual, sin tocar el externo","El externo, sin tocar los demás"],"answer":0,"why":"El interno: los índices y rutas de acceso son estructura de almacenamiento. Nada del conceptual cambia — las mismas entidades, los mismos atributos, las mismas restricciones. Por eso ninguna consulta hay que reescribirla."},{"id":"0003-tres-niveles#2","lesson":"0003-tres-niveles","block":"fund","q":"Se agrega el atributo <code>Prepaga</code> a Paciente. La vista de Facturación, que nunca lo menciona, sigue funcionando sin cambios. ¿Qué se demostró?","options":["Independencia lógica de los datos","Independencia física de los datos"],"answer":0,"why":"Cambió el esquema conceptual y los externos no se enteraron: eso es independencia lógica. Y es la difícil — si en vez de agregar hubieras QUITADO un atributo que la vista sí usa, se habría roto."},{"id":"0003-tres-niveles#3","lesson":"0003-tres-niveles","block":"fund","q":"De los tres esquemas, ¿en cuál están guardados los datos reales?","options":["En ninguno: los tres son descripciones","En el interno, que es el más bajo","En el conceptual, que los describe"],"answer":0,"why":"Correcto, y es un punto que se pregunta. Los tres esquemas son SÓLO descripciones. Los datos existen únicamente en el nivel físico, en la base de datos almacenada — la banda punteada del dibujo."},{"id":"0004-estructura-relacional#1","lesson":"0004-estructura-relacional","block":"fund","q":"La relación de arriba tiene 4 columnas y 3 filas. Insertás dos estudiantes más. ¿Qué cambió?","options":["La cardinalidad, ahora vale cinco","El grado, que ahora vale cinco","Nada de eso: sólo cambió el orden"],"answer":0,"why":"La cardinalidad pasó de 3 a 5; el grado sigue en 4. Regla mnemotécnica: el grado lo fija el esquema y casi nunca cambia; la cardinalidad la fija el estado y cambia con cada operación."},{"id":"0004-estructura-relacional#2","lesson":"0004-estructura-relacional","block":"fund","q":"Corrés dos veces el mismo <code>SELECT</code> sin <code>ORDER BY</code> y las filas salen en distinto orden. ¿El motor tiene un error?","options":["No: el orden nunca estuvo garantizado","Sí: debería respetar el orden natural"],"answer":0,"why":"Una relación es un conjunto y los conjuntos no tienen orden. Si no pediste ORDER BY, no pediste orden, y el motor es libre de devolverlas como le convenga. Depender de un orden accidental es un bug tuyo, no del motor."},{"id":"0004-estructura-relacional#3","lesson":"0004-estructura-relacional","block":"fund","q":"Declarás <code>Año</code> como <code>INTEGER</code>, y alguien carga un estudiante de año <code>47</code>. ¿Qué falló?","options":["El dominio quedó sin declarar completo","La integridad referencial no se cumplió","El estado de relación estaba vacío"],"answer":0,"why":"El tipo de dato no es el dominio. INTEGER acepta 47 sin chistar; el dominio real era 'entero entre 1 y 5' y esa parte nunca se declaró. Todo dominio que no declarás termina siendo responsabilidad de la aplicación — o de nadie."},{"id":"0005-claves-e-integridad#1","lesson":"0005-claves-e-integridad","block":"fund","q":"En <code>ESTUDIANTE(Legajo, DNI, Nombre, Año)</code> con Legajo y DNI únicos, ¿qué es <code>{DNI, Año}</code>?","options":["Superclave, pero no es clave","Clave candidata de la relación","No identifica: Año se repite"],"answer":0,"why":"No se repite en dos tuplas, así que es superclave. Pero no es mínima: sacándole Año, {DNI} sigue identificando. Le sobra un atributo, y eso la descalifica como clave."},{"id":"0005-claves-e-integridad#2","lesson":"0005-claves-e-integridad","block":"fund","q":"Insertás una farmacia sin completar <code>Id_Farmacia</code>, que es su clave primaria. ¿Qué restricción se viola?","options":["Integridad de entidad, por el NULL","Integridad referencial, por el NULL"],"answer":0,"why":"Integridad de entidad: ninguna clave primaria puede ser NULL. Con la clave en NULL la tupla no es identificable, y como NULL significa 'desconocido', ni siquiera se puede comparar contra otra clave NULL."},{"id":"0005-claves-e-integridad#3","lesson":"0005-claves-e-integridad","block":"fund","q":"Borrás la ciudad <i>Rosario</i>. Existen tres farmacias cuya clave foránea apunta a ella. ¿Qué pasa?","options":["Se viola la integridad referencial","Se borran las tres farmacias también","No pasa nada: son tablas distintas"],"answer":0,"why":"Correcto: quedarían tres referencias apuntando a una tupla inexistente, que es exactamente lo que la integridad referencial prohíbe. Qué hace el motor al respecto — rechazar, propagar el borrado o poner NULL — se declara con ON DELETE, y lo vemos en la lección 0036."},{"id":"0006-ciclo-de-vida#1","lesson":"0006-ciclo-de-vida","block":"fund","q":"En el parcial dibujás un diagrama lineal de seis cajas que termina en <i>Despliegue → Mantenimiento</i>, con una flecha de retorno. ¿Qué pasa?","options":["Es el ciclo de vida del software, no el de la cátedra","Es lo mismo, sólo que con más detalle","Sirve igual: lo importante es la flecha de retorno"],"answer":0,"why":"Ése es el ciclo de vida del SOFTWARE, no el de la base de datos que dio la cátedra. Le faltan las dos marcas propias del de BD: la etapa de Captura y la apertura de Diseño en conceptual, lógico y físico."},{"id":"0006-ciclo-de-vida#2","lesson":"0006-ciclo-de-vida","block":"fund","q":"Estás decidiendo si el modelo va a PostgreSQL o a SQL Server, y con qué metodología se va a cargar. ¿En qué etapa estás?","options":["Implementación","Diseño","Captura"],"answer":0,"why":"Implementación. La cátedra la define exactamente así: 'darán paso a la selección de la base de datos y metodología a implementar'. La elección del motor NO es diseño conceptual — el conceptual es agnóstico del producto."},{"id":"0006-ciclo-de-vida#3","lesson":"0006-ciclo-de-vida","block":"fund","q":"¿Qué justifica dibujarlo como círculo en vez de como lista?","options":["Que la operación genera requerimientos nuevos y vuelve a abrir el análisis","Que las cuatro etapas se pueden hacer en cualquier orden","Que queda más prolijo en la hoja"],"answer":0,"why":"Exacto. La operación produce dos cosas que reabren el ciclo: requerimientos nuevos, porque la organización cambia, y problemas de calidad de datos. Por eso no hay una etapa final."},{"id":"0010-razon-de-cardinalidad#1","lesson":"0010-razon-de-cardinalidad","block":"der","q":"TP1: \"Cada farmacia tiene sus propios empleados.\" Un empleado trabaja en una sola farmacia. ¿Cómo queda marcado el tramo de cada lado?","options":["1 junto a Farmacia, N junto a Empleado","N junto a Farmacia, 1 junto a Empleado","N junto a Farmacia, N junto a Empleado"],"answer":0,"why":"La razón es Farmacia : Empleado = 1 : N. El 1 va pegado a Farmacia porque un empleado pertenece a una sola farmacia; la N va pegada a Empleado porque una farmacia tiene muchos. Así lo marca la resolución oficial: el conector hacia Farmacia es One y el conector hacia Empleado es Many."},{"id":"0010-razon-de-cardinalidad#2","lesson":"0010-razon-de-cardinalidad","block":"der","q":"En <code>Laboratorio —Crea— Medicamento</code>, la <code>N</code> está escrita del lado Medicamento. ¿Qué cuenta exactamente esa N?","options":["Cuántos medicamentos hay por laboratorio","Cuántos laboratorios hay por medicamento"],"answer":0,"why":"Exacto: se lee cruzada. La marca está pegada a Medicamento y cuenta medicamentos, pero la unidad de referencia es la entidad del otro extremo — un laboratorio."},{"id":"0010-razon-de-cardinalidad#3","lesson":"0010-razon-de-cardinalidad","block":"der","q":"Misma relación, ahora en notación (mín, máx) de Elmasri. Sabiendo que un laboratorio crea muchos medicamentos, ¿qué par va del lado <b>Laboratorio</b>?","options":["El par (1,N), no el (1,1)","El par (1,1), no el (1,N)"],"answer":0,"why":"Correcto, y fijate el cruce: donde la razón de cardinalidad escribe 1, el par (mín, máx) escribe (1,N). El par describe la participación del propio laboratorio: participa en al menos una y como mucho N instancias de Crea."},{"id":"0013-especializacion-la-notacion-isa#1","lesson":"0013-especializacion-la-notacion-isa","block":"der","q":"¿Qué significa el círculo entre el supertipo y el triángulo ISA?","options":["Que la especialización es total","Que los subtipos son exclusivos","Que los subtipos se solapan entre sí","Que los subtipos tienen atributos"],"answer":0,"why":"Correcto. Círculo = total: todo registro del supertipo pertenece a algún subtipo. Sin círculo, la especialización es parcial."},{"id":"0013-especializacion-la-notacion-isa#2","lesson":"0013-especializacion-la-notacion-isa","block":"der","q":"\"Un participante de la película puede ser actor y director.\" ¿Qué restricción fija esa frase?","options":["Solapada, y se dibuja sin arco","Exclusiva, y se dibuja con arco","Total, y se dibuja con círculo","Parcial, y se dibuja sin círculo"],"answer":0,"why":"Correcto. Un individuo cae en dos subtipos a la vez, así que la especialización es solapada: se dibuja sin arco. Es el ejemplo del slide 26."},{"id":"0014-contar-registros-del-supertipo#1","lesson":"0014-contar-registros-del-supertipo","block":"der","q":"Subtipos A=40 y B=10, especialización total y solapada. ¿Cuántos registros tiene el supertipo?","options":["Entre 40 y 50 registros","Exactamente 50 registros","50 registros o más","Entre 10 y 50 registros"],"answer":0,"why":"Correcto. Total pone el techo en 50; el piso es el subtipo más grande, 40, que se da si los 10 de B están todos dentro de A."},{"id":"0014-contar-registros-del-supertipo#2","lesson":"0014-contar-registros-del-supertipo","block":"der","q":"¿Cuál de las cuatro combinaciones permite responder con un número exacto?","options":["Total y exclusiva, la suma","Total y solapada, la suma","Parcial y exclusiva, la suma","Parcial y solapada, la suma"],"answer":0,"why":"Correcto. Total fija el techo y exclusiva fija el piso: los dos coinciden en la suma de los subtipos, así que la cuenta es cerrada."},{"id":"0019-las-anomalias#1","lesson":"0019-las-anomalias","block":"norm","q":"¿Por qué la factura 1 puede tener dos fechas distintas, si en el mundo real una factura tiene una sola?","options":["La fecha se repite en cada renglón","Alguien se equivocó al cargar el dato","La factura se emitió en dos partes"],"answer":0,"why":"Exacto. La clave de esa tabla es (NFact, CProd), no NFact. Como cada renglón es una fila y cada fila trae su copia de la fecha, nada impide que dos copias difieran. La estructura permite lo que la realidad prohíbe: ése es el defecto."},{"id":"0019-las-anomalias#2","lesson":"0019-las-anomalias","block":"norm","q":"¿Por qué <code>PcioT</code> es el peor atributo de toda la tabla?","options":["Es derivado y además está repetido","Es numérico y ocupa mucho espacio"],"answer":0,"why":"Es derivado Y se repite en cada renglón de la factura. Doble falta: se puede recalcular, y encima está copiado ocho veces. Cualquier renglón que cambie deja desactualizadas todas las copias del total."},{"id":"0019-las-anomalias#3","lesson":"0019-las-anomalias","block":"norm","q":"El producto 44 (Tomates) aparece sólo en la factura 2. Borrás esa factura. ¿Qué anomalía es?","options":["De borrado: se pierde otro hecho","De inserción: no se puede dar alta","De modificación: hay que tocar todo"],"answer":0,"why":"De borrado: al eliminar un hecho — la factura — perdiste otro que no querías perder, la existencia del producto 44. Dos hechos independientes viven en la misma fila, y por eso mueren juntos."},{"id":"0020-dependencia-funcional#1","lesson":"0020-dependencia-funcional","block":"norm","q":"En una tabla ves dos filas con el mismo <code>CProd</code> y distinta <code>Descri</code>. ¿Qué concluís?","options":["Los datos están mal, no la dependencia","La dependencia no vale, según los datos","Un producto tiene dos descripciones"],"answer":0,"why":"Correcto. La dependencia CProd → Descri vale por el significado: un producto tiene una descripción. Los datos que la violan son datos sucios, y son justamente la anomalía que la normalización viene a hacer imposible."},{"id":"0020-dependencia-funcional#2","lesson":"0020-dependencia-funcional","block":"norm","q":"Clave primaria <code>(NFact, CProd)</code>. Sabés que <code>CProd &rarr; Descri</code>. ¿Qué tipo de dependencia es respecto de esa clave?","options":["Parcial, porque le sobra el NFact","Transitiva, porque pasa por CProd","Total, porque CProd está en clave"],"answer":0,"why":"Parcial: le alcanza con CProd, que es sólo una parte de la clave. Sacando NFact la dependencia sigue valiendo, y ése es exactamente el test de parcialidad. Rompe 2FN."},{"id":"0020-dependencia-funcional#3","lesson":"0020-dependencia-funcional","block":"norm","q":"Una tabla tiene clave primaria de un solo atributo. ¿Qué podés afirmar sin revisar nada?","options":["Está en 2FN, y falta revisar 3FN","Está en 3FN, no hay nada que ver"],"answer":0,"why":"Si la clave es un solo atributo no existe 'parte de la clave', así que ninguna dependencia parcial es posible. Está en 2FN por construcción. Todavía puede violar 3FN, que es lo único que te queda por revisar."},{"id":"0021-primera-forma-normal#1","lesson":"0021-primera-forma-normal","block":"norm","q":"Tabla <code>Empleado(Legajo, Nombre, Telefonos)</code> donde <code>Telefonos</code> guarda <code>\"4555-1234 / 4555-9876\"</code>. ¿Está en 1FN?","options":["No, y va a una tabla aparte","Sí, porque es un solo campo texto"],"answer":0,"why":"No: hay más de un valor en una celda. Se arregla con Empleado(#Legajo, Nombre) y EmpleadoTelefono(#Legajo, #Telefono). Fijate que el teléfono es parte de la clave: es lo que distingue una fila de otra del mismo empleado."},{"id":"0021-primera-forma-normal#2","lesson":"0021-primera-forma-normal","block":"norm","q":"Al separar los renglones, ¿por qué la clave de <code>RenglonFact</code> es <code>(NFact, CProd)</code> y no sólo <code>CProd</code>?","options":["Un producto está en varias facturas","Porque NFact va primero en la tabla","Porque NFact es una clave foránea"],"answer":0,"why":"El mismo producto aparece en varias facturas: CProd 35 está en la 1 y en la 3, CProd 37 en la 1 y en la 2. Sólo con CProd habría filas repetidas. Hace falta saber DE QUÉ FACTURA es el renglón."},{"id":"0021-primera-forma-normal#3","lesson":"0021-primera-forma-normal","block":"norm","q":"Después de 1FN, ¿el producto 39 puede seguir apareciendo como \"Kiwi\" y como \"Kivi\"?","options":["Sí: las claves de esas filas difieren","No: 1FN unificó las descripciones"],"answer":0,"why":"Sí, y ahí está el límite de 1FN. En RenglonFact las dos filas tienen clave distinta —(1,39) y (2,39)— así que nada impide descripciones distintas. Esa anomalía la elimina 2FN, en la lección que sigue."},{"id":"0022-segunda-forma-normal#1","lesson":"0022-segunda-forma-normal","block":"norm","q":"<code>CabeceraFact(#NFact, Fecha, CodCli, NomCli)</code>. ¿Cuánto trabajo da revisar si está en 2FN?","options":["Ninguno: la clave es un solo campo","Hay que revisar NomCli con cuidado"],"answer":0,"why":"Ninguno: la clave es NFact, un solo atributo. No hay 'parte de la clave' de la cual algo pueda depender parcialmente, así que está en 2FN por construcción. Ojo que esto NO dice nada sobre 3FN — y de hecho esa tabla la viola."},{"id":"0022-segunda-forma-normal#2","lesson":"0022-segunda-forma-normal","block":"norm","q":"<code>Inscripcion(#Legajo, #CodMateria, Nota, NombreMateria)</code>. ¿Qué viola 2FN?","options":["NombreMateria, que sale de media clave","Nota, que depende de dos campos","Nada: la tabla ya cumple con 2FN"],"answer":0,"why":"NombreMateria depende sólo de CodMateria, que es media clave. La materia se llama igual sin importar quién se inscriba. Se muda a Materia(#CodMateria, NombreMateria)."},{"id":"0022-segunda-forma-normal#3","lesson":"0022-segunda-forma-normal","block":"norm","q":"Al mudar <code>Descri</code> a <code>Prod</code>, ¿qué pasa con <code>CProd</code> en <code>RenglonFact</code>?","options":["Se queda, y además pasa a ser foránea","Se va, porque ahora vive en Prod"],"answer":0,"why":"Se queda, y suma un rol: sigue siendo parte de la clave primaria del renglón, y ahora además es clave foránea hacia Prod. Un mismo atributo puede cumplir los dos papeles a la vez."},{"id":"0023-tercera-forma-normal#1","lesson":"0023-tercera-forma-normal","block":"norm","q":"<code>Empleado(#Legajo, Nombre, CodDepto, NombreDepto)</code>. ¿Qué forma normal se viola?","options":["La 3FN, por NombreDepto","La 2FN, por NombreDepto","La 1FN, por tener dos temas"],"answer":0,"why":"3FN: NombreDepto depende de CodDepto, que no es clave. La cadena es Legajo → CodDepto → NombreDepto. Se arregla con Depto(#CodDepto, NombreDepto) y dejando CodDepto como foránea en Empleado."},{"id":"0023-tercera-forma-normal#2","lesson":"0023-tercera-forma-normal","block":"norm","q":"<code>Persona(#DNI, Nombre, NroPasaporte, PaisEmisor)</code>, donde <code>NroPasaporte</code> es único por persona. ¿<code>PaisEmisor</code> viola 3FN?","options":["No, porque NroPasaporte es candidata","Sí, hay una cadena de dos saltos"],"answer":0,"why":"NroPasaporte es único, así que es clave candidata. Elmasri exige que el intermediario NO sea clave candidata para que haya transitividad. Al serlo, no hay violación: es la letra chica que evita descomponer de más."},{"id":"0023-tercera-forma-normal#3","lesson":"0023-tercera-forma-normal","block":"norm","q":"Tu modelo quedó en 3FN. ¿Qué podés afirmar?","options":["No hay parciales ni transitivas. Nada más.","El modelo ya no tiene ninguna anomalía."],"answer":0,"why":"Exacto, y es la lección entera. 3FN elimina la redundancia causada por dependencias parciales y transitivas. No dice nada sobre si elegiste bien las entidades, si el modelo contesta las consultas pedidas, ni sobre el PUnit del renglón."},{"id":"0024-donde-vive-el-precio#1","lesson":"0024-donde-vive-el-precio","block":"norm","q":"Un N:N entre <code>Alumno</code> y <code>Materia</code>, y de cada cursada interesa la nota. ¿Cómo queda la tabla asociativa?","options":["Cursa(#Legajo, #CodMateria, Nota)","Cursa(#Legajo, CodMateria, Nota)","Cursa(#IdCursa, Legajo, CodMateria)"],"answer":0,"why":"La clave es la unión de las dos claves, y Nota va adentro porque pertenece al vínculo: no es del alumno ni de la materia, es de la combinación. En el DER colgaba del rombo."},{"id":"0024-donde-vive-el-precio#2","lesson":"0024-donde-vive-el-precio","block":"norm","q":"El enunciado dice: \"se necesita saber a qué precio se vendió cada producto en cada momento del año\". ¿Qué modelo?","options":["El histórico, con la fecha en la clave","El precio como atributo del producto"],"answer":0,"why":"Situación C. 'En cada momento' mete el tiempo en el problema, y el tiempo se modela entrando en la clave primaria: PrecioProd(#CProd, #FechaDesde, Precio)."},{"id":"0024-donde-vive-el-precio#3","lesson":"0024-donde-vive-el-precio","block":"norm","q":"En la tabla <code>PrecioProd</code>, el producto 39 aparece con 10 y con 11. ¿Volvió la anomalía?","options":["No: son dos hechos distintos, fechados","Sí: el mismo producto tiene dos precios"],"answer":0,"why":"No: la clave ahora es (CProd, FechaDesde), así que son dos filas distintas describiendo dos hechos distintos. Antes eran dos respuestas contradictorias a una misma pregunta; ahora son dos respuestas a dos preguntas distintas."},{"id":"0025-integrador-ordenes#1","lesson":"0025-integrador-ordenes","block":"norm","q":"¿Por qué <code>ESTADO</code> se va a <code>CLIENTES</code> y no se queda en la orden?","options":["Depende del cliente, no de la orden","Es el estado de avance de la orden"],"answer":0,"why":"Es un dato del cliente — su ciudad o estado — no de la orden. Depende de ID_CLIENTE, que en ORDEN_CLIENTES no es clave: dependencia transitiva de manual. Viaja junto con NOM_CLIENTE porque las dos dependen del mismo atributo."},{"id":"0025-integrador-ordenes#2","lesson":"0025-integrador-ordenes","block":"norm","q":"Por la definición estricta, mudar <code>PRECIO</code> a <code>ARTICULOS</code>, ¿qué paso es?","options":["2FN: depende de parte de la clave","3FN: depende de un campo no clave"],"answer":0,"why":"Es 2FN: PRECIO depende de NUM_ART, que es una PARTE de la clave compuesta (ID_ORDEN, NUM_ART). Eso es una dependencia parcial por definición. En la resolución se hace en el paso 3, pero el resultado final es idéntico."},{"id":"0025-integrador-ordenes#3","lesson":"0025-integrador-ordenes","block":"norm","q":"¿Cómo verificás que no perdiste información al normalizar?","options":["Reconstruís la tabla original con joins","Contás que las filas sumen las mismas"],"answer":0,"why":"Reconstruir la tabla original uniendo las cuatro por sus claves. Si te da exactamente las seis filas del principio, la descomposición no perdió nada. Es el control que casi nadie hace y el que más errores encuentra."},{"id":"0026-integrador-proveedores#1","lesson":"0026-integrador-proveedores","block":"norm","q":"<code>DIRECCION</code> genera columnas y <code>TELEFONO</code> genera una tabla. ¿Por qué el trato distinto?","options":["Uno es un valor, el otro son varios","La dirección tiene menos partes"],"answer":0,"why":"Una dirección es un valor con partes: calle y número, una sola vez. Entra en columnas. Los teléfonos son varios valores del mismo tipo: no entran en una columna sin violar 1FN, así que necesitan filas."},{"id":"0026-integrador-proveedores#2","lesson":"0026-integrador-proveedores","block":"norm","q":"En AFECTADO, <code>PROVEEDOR 1 : N PEDIDO</code>. ¿Por qué la FK no va en PROVEEDOR?","options":["Serían muchos valores en una columna","Porque la relación nace en el pedido","Porque PEDIDO tiene clave primaria"],"answer":0,"why":"Habría que guardar muchos números de pedido en la fila del proveedor, y eso es un grupo repetitivo: violación de 1FN. Del lado N sólo hay un valor por fila, que sí entra en una columna."},{"id":"0026-integrador-proveedores#3","lesson":"0026-integrador-proveedores","block":"norm","q":"¿Podría <code>Cantidad</code> haber quedado en <code>PEDIDO</code> en lugar de en <code>PEDIDO_MATERIAL</code>?","options":["No: hay una cantidad por material","Sí: la cantidad es del pedido entero"],"answer":0,"why":"No: un pedido lleva varios materiales, cada uno con su propia cantidad. En PEDIDO habría una sola cantidad para todo el pedido, que no significa nada. Cantidad depende de la combinación pedido-material, y por eso vive en la asociativa."},{"id":"0027-almacenamiento-y-archivos#1","lesson":"0027-almacenamiento-y-archivos","block":"fis","q":"Un programa necesita un registro que está en un disco duro. ¿Qué pasa primero?","options":["Se copia al almacenamiento principal","La CPU lo procesa donde está","La caché lo lee desde el disco"],"answer":0,"why":"El disco es almacenamiento secundario, y la CPU no puede procesar ahí directamente. El bloque se copia a la memoria principal, se procesa, y se reescribe en disco sólo si el dato cambió."},{"id":"0027-almacenamiento-y-archivos#2","lesson":"0027-almacenamiento-y-archivos","block":"fis","q":"¿Por qué el material clasifica la cinta magnética como almacenamiento <em>offline</em>?","options":["Alguien tiene que cargarla antes","Su acceso resulta bastante lento","Resulta más costosa que el disco"],"answer":0,"why":"Textual: para que los datos estén disponibles se necesita antes la intervención de un operador, o de un dispositivo de carga automática, para cargar la cinta. El disco, en cambio, es online: acceso directo en cualquier momento."},{"id":"0028-indices#1","lesson":"0028-indices","block":"fis","q":"¿Cuál de todos los índices ordena físicamente los campos?","options":["El índice agrupado","El índice principal","El índice secundario"],"answer":0,"why":"Y la justificación: las filas de la tabla se ordenan en el mismo orden que el índice, de modo que quedan físicamente almacenadas juntas en el disco. Es la pregunta textual que dio el docente en clase."},{"id":"0028-indices#2","lesson":"0028-indices","block":"fis","q":"¿Qué índice tiene como <b>costo</b> el mayor espacio de almacenamiento?","options":["El secundario, por su estructura aparte","El agrupado, por su orden físico","El principal, por su clave única"],"answer":0,"why":"El secundario, porque crea una estructura de índice separada del fichero de datos. El material le marca además que un uso excesivo degrada el rendimiento."},{"id":"0028-indices#3","lesson":"0028-indices","block":"fis","q":"¿Por qué en una tabla puede haber un solo índice principal?","options":["Porque la clave primaria es única","Porque el orden físico es único","Porque cada fila ocupa un bloque"],"answer":0,"why":"Textual del material: solo puede haber un índice primario, ya que la clave primaria es única en la tabla. Una tabla tiene una sola clave primaria, entonces un solo índice principal."},{"id":"0028-indices#4","lesson":"0028-indices","block":"fis","q":"¿Por qué el índice principal es un índice <b>no denso</b>?","options":["Tiene una entrada por cada bloque","Tiene una entrada por cada registro","Tiene una entrada por cada tabla"],"answer":0,"why":"Porque incluye una entrada por cada bloque de disco del fichero, en lugar de una por cada registro. Denso significa una entrada por cada valor de la clave de búsqueda, y por tanto por cada registro."},{"id":"0029-store-procedures-y-triggers#1","lesson":"0029-store-procedures-y-triggers","block":"sql","q":"Querés impedir que se cargue una internación en una habitación llena. ¿Qué tipo de trigger usás?","options":["BEFORE INSERT sobre OCUPACION","AFTER INSERT sobre la OCUPACION","INSTEAD OF sobre la OCUPACION"],"answer":0,"why":"BEFORE: corre antes de que la fila entre, y puede abortar la operación. El deck lo describe justo así: útil para chequear restricciones que no se pueden verificar mediante referencias."},{"id":"0029-store-procedures-y-triggers#2","lesson":"0029-store-procedures-y-triggers","block":"sql","q":"¿Cuál de estas frases describe a un store procedure y no a un trigger?","options":["Se ejecuta cuando alguien lo llama","Se dispara al insertar en la tabla","Accede a las filas NEW y la OLD"],"answer":0,"why":"Correcto. Al procedimiento lo invoca alguien, con CALL, y puede recibir parámetros IN y OUT. El trigger nunca se llama: se dispara por un evento."},{"id":"0029-store-procedures-y-triggers#3","lesson":"0029-store-procedures-y-triggers","block":"sql","q":"Según el deck, ¿con qué sentencia se ejecuta un store procedure?","options":["SELECT nombre(args);","CALL nombre(args);","No se ejecuta: se dispara solo"],"answer":1,"why":"Correcto. Slide 18: &quot;Para ejecutar se debe generar la siguiente sentencia: CALL &amp;lt;nombre del procedimiento o función&amp;gt; «lista de argumentos»&quot;. Es la pregunta 5 del Examen1."},{"id":"0029-store-procedures-y-triggers#4","lesson":"0029-store-procedures-y-triggers","block":"sql","q":"¿Para qué sirve un trigger <code>INSTEAD OF</code>?","options":["Para validar antes de tocar la tabla","Para propagar cambios en cascada","Para hacer actualizables las vistas"],"answer":2,"why":"Correcto. Slide 22: &quot;INSTEAD OF: se aplica en vistas, para hacerlas actualizables&quot;. Es el único de los tres que no va sobre tablas."},{"id":"0029-store-procedures-y-triggers#5","lesson":"0029-store-procedures-y-triggers","block":"sql","q":"Según el deck, ¿qué activa un trigger?","options":["Una sentencia DML: INSERT, UPDATE o DELETE","Un CALL desde la aplicación","Un CREATE o un ALTER"],"answer":0,"why":"Correcto. Slide 21: &quot;se activan cuando se modifica la data mediante cualquier evento de una sentencia DML&quot;."},{"id":"0029-store-procedures-y-triggers#6","lesson":"0029-store-procedures-y-triggers","block":"sql","q":"¿Cuál de estas <b>no</b> es una de las circunstancias en que el deck dice que un SP es útil?","options":["Varias aplicaciones usan el mismo programa","Garantizar la integridad referencial","Bajar el tráfico entre cliente y servidor"],"answer":1,"why":"Correcto, esa no está. La integridad referencial la garantiza la FOREIGN KEY. El deck da tres: menos duplicidad (modularidad), menos costo de comunicación cliente–servidor y derivados más complejos en las vistas."},{"id":"0029-store-procedures-y-triggers#7","lesson":"0029-store-procedures-y-triggers","block":"sql","q":"En <code>SueldoTotal1</code> (AFTER INSERT ON EMPLEADO), ¿qué es <code>NEW.Sueldo</code>?","options":["El sueldo total del departamento","Un parámetro IN del trigger","El sueldo del empleado recién insertado"],"answer":2,"why":"Correcto. NEW es la fila que acaba de entrar. El trigger suma ese sueldo al SueldoTotal del departamento del empleado, si Dno no es NULL."},{"id":"0029-store-procedures-y-triggers#8","lesson":"0029-store-procedures-y-triggers","block":"sql","q":"En <code>GET_LOAD_ID</code>, ¿qué devuelve el parámetro <code>OUT Load_id</code>?","options":["El Load_Id de la fila de log que acaba de insertar","La fecha y la hora de la carga","El nombre del paquete DTS"],"answer":0,"why":"Correcto. Registra el paquete con la fecha y hora actuales en LOAD_INSTANCE_LOG y después busca esa misma fila (paquete + fecha + hora) para devolver su Load_Id. Es la pregunta 7 del Examen1."},{"id":"0031-ddl-create-table#1","lesson":"0031-ddl-create-table","block":"sql","q":"En <code>PACIENTE</code>, ¿qué restricción declara que <code>Cod_Prepaga</code> tiene que existir en la tabla <code>PREPAGA</code>?","options":["Una restricción FOREIGN KEY","Una restricción de UNIQUE","Una restricción de CHECK"],"answer":0,"why":"La FOREIGN KEY fuerza la integridad referencial: el valor tiene que existir como PK en la tabla padre, o ser NULL."},{"id":"0031-ddl-create-table#2","lesson":"0031-ddl-create-table","block":"sql","q":"¿Por qué esta sentencia es inválida según el deck? <code>codigo INT NOT NULL PRIMARY KEY</code>","options":["La PK ya implica el NOT NULL","La PK va a nivel de la tabla","INT no sirve como clave PK"],"answer":0,"why":"El deck lo marca como no válido: la PRIMARY KEY ya implica NOT NULL, y declarar las dos condiciones hace que el motor arroje error. En la práctica muchos motores lo aceptan, pero en el parcial vale lo que dice el material."},{"id":"0031-ddl-create-table#3","lesson":"0031-ddl-create-table","block":"sql","q":"Si en el CREATE TABLE no ponés ni <code>NULL</code> ni <code>NOT NULL</code>, ¿qué pasa con la columna?","options":["Da error: es obligatorio declararlo","Acepta NULL","Queda NOT NULL"],"answer":1,"why":"Correcto. Slide 3: &quot;Si no específica NULL o NOT NULL, se utiliza el valor predeterminado, el cuál es que las columnas se creen con la opción NULL&quot;."},{"id":"0031-ddl-create-table#4","lesson":"0031-ddl-create-table","block":"sql","q":"La clave de <code>Curso</code> es <code>(codigo_curso, codigo_categoria)</code>. ¿Dónde se declara?","options":["A nivel tabla, con CONSTRAINT … PRIMARY KEY (a, b)","Poniendo PRIMARY KEY en cada una de las dos columnas","Da igual: columna o tabla"],"answer":0,"why":"Correcto. Slides 6–8: a nivel columna &quot;sólo es admitida en los casos donde la misma no sea compuesta&quot;. A nivel tabla vale para las dos."},{"id":"0031-ddl-create-table#5","lesson":"0031-ddl-create-table","block":"sql","q":"Según el deck, ¿qué puede referenciar una restricción <code>CHECK</code>?","options":["Columnas de otra tabla","La PK de la tabla padre","Una sola columna, de la misma tabla"],"answer":2,"why":"Correcto. Slide 12: &quot;Solo puede referenciar una columna y debe ser de la misma tabla&quot;. Restringe el dominio de un campo."},{"id":"0031-ddl-create-table#6","lesson":"0031-ddl-create-table","block":"sql","q":"En una relación padre–hijo, ¿qué valores puede tomar la columna FK de la tabla hija?","options":["Los de la PK del padre, más NULL","Sólo los del padre, nunca NULL","Cualquiera de cualquier columna del padre"],"answer":0,"why":"Correcto. Slide 10: &quot;Los valores de los campos de la tabla referenciada (Tabla Padre) mas el valor Null forman el conjunto de valores posibles&quot;. Para prohibir el NULL hay que agregar NOT NULL."},{"id":"0032-select-basico#1","lesson":"0032-select-basico","block":"sql","q":"<code>SELECT DISTINCT Cod_Paciente, Diagnostico FROM HISTORIA_CLINICA</code>. José tiene dos consultas, las dos con \"Hipertensión\". ¿Cuántas filas suyas aparecen?","options":["Aparece en una sola fila","Aparece en dos filas iguales","No aparece en el resultado"],"answer":0,"why":"Una. DISTINCT compara la fila que devolvés, que acá es (Cod_Paciente, Diagnostico). Las dos consultas de José dan (5, 'Hipertensión'), la misma fila, y queda una sola."},{"id":"0032-select-basico#2","lesson":"0032-select-basico","block":"sql","q":"Según el deck, ¿cuánto existe un alias como <code>FROM ENVIOS E</code>?","options":["Hasta que se borre la tabla","Sólo mientras dura esa consulta","Hasta que termine la sesión"],"answer":1,"why":"Correcto. Slide 5: &quot;Un alias solo existe mientras dura esa consulta&quot;. El &lt;code&gt;AS&lt;/code&gt; es opcional."},{"id":"0033-condiciones-y-null#1","lesson":"0033-condiciones-y-null","block":"sql","q":"<code>WHERE Cant_Camas BETWEEN 1 AND 2</code>. ¿Qué habitaciones entran?","options":["= 1 AND Cant_Camas Las de una y las de dos camas","= 1 AND Sólo las que tienen una cama","Ninguna: no hay entero entre"],"answer":0,"why":""},{"id":"0033-condiciones-y-null#2","lesson":"0033-condiciones-y-null","block":"sql","q":"Hay profesionales sin jefe (<code>Cod_Jefe</code> NULL). ¿Qué devuelve <code>WHERE Cod_Profesional NOT IN (SELECT Cod_Jefe FROM PROFESIONAL)</code>?","options":["Los profesionales que no son jefe de nadie","Ninguna fila","Un error de sintaxis"],"answer":1,"why":"Correcto, y sin dar error. Basta con un NULL en la lista para que NOT IN no devuelva nada. Usá NOT EXISTS, o agregá WHERE Cod_Jefe IS NOT NULL dentro de la subconsulta."},{"id":"0033-condiciones-y-null#3","lesson":"0033-condiciones-y-null","block":"sql","q":"¿Aparecen los profesionales sin jefe con <code>WHERE Cod_Jefe &lt;&gt; 1</code>?","options":["No","Sí: NULL es distinto de 1","Sólo si la columna admite NULL"],"answer":0,"why":"Correcto. NULL &amp;lt;&amp;gt; 1 no es VERDADERO: es DESCONOCIDO, y el WHERE sólo deja pasar VERDADERO. Para incluirlos: &lt;code&gt;WHERE Cod_Jefe &amp;lt;&amp;gt; 1 OR Cod_Jefe IS NULL&lt;/code&gt;."},{"id":"0034-joins#1","lesson":"0034-joins","block":"sql","q":"Hay 10 pacientes y 9 teléfonos, de 7 pacientes distintos. ¿Cuántas filas devuelve <code>PACIENTE LEFT JOIN PACIENTE_TELEFONO</code>?","options":["Doce filas en total, 9 + 3","Nueve filas, una por teléfono","Diez filas, una por paciente"],"answer":0,"why":"12. Los 7 pacientes con teléfono generan una fila por teléfono (9 filas). Los 3 sin teléfono aparecen una vez cada uno, con NULL a la derecha (3 filas)."},{"id":"0034-joins#2","lesson":"0034-joins","block":"sql","q":"<code>FROM T1, T2 WHERE T1.x = T2.x</code> da el mismo resultado que…","options":["T1 CROSS JOIN T2","T1 LEFT JOIN T2 ON T1.x = T2.x","T1 JOIN T2 ON T1.x = T2.x"],"answer":2,"why":"Correcto. El slide 26 muestra las dos escrituras juntas. JOIN a secas es INNER JOIN."},{"id":"0034-joins#3","lesson":"0034-joins","block":"sql","q":"¿En qué se diferencian <code>UNION</code> y <code>UNION ALL</code>?","options":["UNION elimina los duplicados; UNION ALL no","UNION ALL exige las mismas columnas y UNION no","UNION junta columnas y UNION ALL junta filas"],"answer":0,"why":"Correcto. Slides 32–33: UNION combina los resultados &quot;en una sola tabla, se eliminan los duplicados&quot;; UNION ALL &quot;NO&quot; los elimina."},{"id":"0035-group-by-having#1","lesson":"0035-group-by-having","block":"sql","q":"\"Cantidad de consultas por servicio, contando sólo las de 2026 en adelante.\" ¿Dónde va la condición de la fecha?","options":["En el WHERE, antes de agrupar","En el HAVING, después de agrupar","Dentro del GROUP BY, como clave"],"answer":0,"why":"En el WHERE. La fecha es de cada fila, no del grupo: hay que descartar las consultas viejas antes de agrupar y contar."},{"id":"0035-group-by-having#2","lesson":"0035-group-by-having","block":"sql","q":"PROFESIONAL tiene 8 filas y 4 de ellas tienen <code>Cod_Jefe</code> NULL. ¿Qué devuelve <code>SELECT COUNT(*), COUNT(Cod_Jefe)</code>?","options":["8 y 8","8 y 4","4 y 4"],"answer":1,"why":"Correcto. Slide 20: COUNT cuenta &quot;el número de filas de una tabla o el número de valores no nulos de una columna&quot;. COUNT(*) cuenta filas; COUNT(Cod_Jefe), valores no nulos."},{"id":"0035-group-by-having#3","lesson":"0035-group-by-having","block":"sql","q":"¿Cuál es el orden en que se escriben, según el resumen del deck?","options":["SELECT, FROM, WHERE, HAVING, GROUP BY, ORDER BY","SELECT, FROM, GROUP BY, WHERE, HAVING, ORDER BY","SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY"],"answer":2,"why":"Correcto. Slide 17, &quot;En resumen…&quot;. WHERE filtra filas, GROUP BY arma los grupos y HAVING los filtra."},{"id":"0036-subconsultas-exists#1","lesson":"0036-subconsultas-exists","block":"sql","q":"¿Qué diferencia marca el deck entre EXISTS e IN?","options":["EXISTS sólo admite subconsultas","EXISTS sólo admite una lista","EXISTS compara valor por valor"],"answer":0,"why":"Es la frase textual del slide 12: EXISTS sólo se puede usar con subconsultas, mientras que IN se puede usar con subconsultas y con listas de valores."},{"id":"0036-subconsultas-exists#2","lesson":"0036-subconsultas-exists","block":"sql","q":"En el ejercicio b, ¿por qué no sirve <code>WHERE T = 'T1' AND T = 'T2'</code> sobre ENVIOS?","options":["Una fila tiene un solo artículo","AND no se usa con columnas texto","No se repite una columna en WHERE"],"answer":0,"why":"WHERE evalúa una fila por vez, y una fila tiene un solo T. «Ambos» habla de dos filas distintas del mismo componente, por eso hace falta preguntar dos veces: IN para T1 y IN para T2."},{"id":"0036-subconsultas-exists#3","lesson":"0036-subconsultas-exists","block":"sql","q":"Según el deck, ¿cuándo es verdadero <code>EXISTS (subconsulta)</code>?","options":["Cuando la subconsulta devuelve al menos una fila","Cuando el valor está en la lista","Cuando la subconsulta no tiene NULL"],"answer":0,"why":"Correcto. Slide 12: &quot;El resultado es verdadero sólo si el número de filas especificadas mediante la selección completa no es cero&quot;. No importa qué columnas traiga: por eso se escribe SELECT *."},{"id":"0037-dml-insert-update-delete#1","lesson":"0037-dml-insert-update-delete","block":"sql","q":"<code>INSERT INTO Prod_Service (Id_Service, Name_Service) SELECT Nombre_Servicio, Id_Servicio FROM Desa_Servicio</code>. ¿Qué pasa?","options":["Se cruzan: van por la posición","Se acomodan solas, por nombre","Siempre falla por la sintaxis"],"answer":0,"why":"Las columnas se emparejan por posición: el nombre cae en Id_Service y el código en Name_Service. Con tipos estrictos da error; con tipos flexibles carga basura. En ningún caso las acomoda por nombre."},{"id":"0037-dml-insert-update-delete#2","lesson":"0037-dml-insert-update-delete","block":"sql","q":"¿Qué hace <code>UPDATE PACIENTE SET Cod_Prepaga = 2;</code>?","options":["Error: falta el WHERE","Cambia la prepaga de todos los pacientes","Cambia sólo la primera fila"],"answer":1,"why":"Correcto. Sin &lt;code&gt;&amp;lt;&amp;lt;search_condition&amp;gt;&amp;gt;&lt;/code&gt;, el UPDATE toca todas las filas de la tabla. Lo mismo pasa con &lt;code&gt;DELETE FROM table;&lt;/code&gt;, que el deck muestra como sentencia válida."},{"id":"0037-dml-insert-update-delete#3","lesson":"0037-dml-insert-update-delete","block":"sql","q":"¿Qué hace un UPSERT (<code>INSERT … ON CONFLICT … DO UPDATE</code>)?","options":["Inserta si la clave no existe y actualiza si ya existe","Inserta y, si falla, borra la fila vieja","Actualiza todas las filas que coinciden con un WHERE"],"answer":0,"why":"Correcto. Slide 37: &quot;inserta una nueva fila si un identificador único especificado no existe o actualiza una fila existente si el mismo identificador ya existe&quot;."},{"id":"0038-alter-drop-on-delete#1","lesson":"0038-alter-drop-on-delete","block":"sql","q":"En <code>PROFESIONAL</code>, <code>Cod_Jefe</code> referencia a otro profesional. Si se borra un jefe, ¿qué conviene declarar en esa FK?","options":["ON DELETE SET NULL en la FK","ON DELETE CASCADE en la FK","Ningún modificador en la FK"],"answer":0,"why":"SET NULL. Los profesionales a cargo siguen trabajando en la clínica: lo único que se pierde es el vínculo con el jefe que se fue. La columna ya admite NULL, porque los jefes no tienen jefe."},{"id":"0038-alter-drop-on-delete#2","lesson":"0038-alter-drop-on-delete","block":"sql","q":"Pregunta 6 del Examen1: eliminar el campo <code>duracion</code> de la tabla <code>Curso</code>.","options":["DROP TABLE Curso;","DELETE duracion FROM Curso;","ALTER TABLE Curso DROP duracion;"],"answer":2,"why":"Correcto. Slide 15. Para agregar el sueldo: &lt;code&gt;ALTER TABLE Curso ADD sueldo DECIMAL(10,2);&lt;/code&gt;."},{"id":"0038-alter-drop-on-delete#3","lesson":"0038-alter-drop-on-delete","block":"sql","q":"La FK no tiene <code>ON DELETE</code>. Borrás un padre que tiene hijos. ¿Qué pasa?","options":["Se borran los hijos","El motor rechaza el borrado","Los hijos quedan con la FK en NULL"],"answer":1,"why":"Correcto. Slide 11: el motor &quot;validará que no exista ningún registro dependiente&quot; en la tabla hija. El modificador ON DELETE no es obligatorio."},{"id":"0039-vistas#1","lesson":"0039-vistas","block":"sql","q":"Creás <code>Vista_Paciente</code> y después insertás un paciente nuevo en <code>PACIENTE</code>. ¿Aparece en la vista?","options":["Sí: la vista se recalcula siempre","No: tiene las filas de su creación","Sólo si se vuelve a crear la vista"],"answer":0,"why":"Sí, en la próxima consulta. La vista guarda el SELECT, no las filas: cada vez que se la consulta, el SELECT corre sobre los datos actuales."},{"id":"0039-vistas#2","lesson":"0039-vistas","block":"sql","q":"¿Qué guarda la base cuando hacés <code>CREATE VIEW</code>?","options":["Una copia de las filas de ese momento","La consulta (el SELECT)","Un índice sobre las tablas base"],"answer":1,"why":"Correcto. La vista es una &quot;representación lógica de un subconjunto de datos&quot;: guarda la definición y la ejecuta cada vez que se la usa."},{"id":"0040-integrador-tp5-clinica#1","lesson":"0040-integrador-tp5-clinica","block":"sql","q":"¿Cuál es la PK de HISTORIA_CLINICA?","options":["Cod_Paciente junto a Id_Consulta","Sólo la columna de Id_Consulta","Cod_Profesional con Id_Consulta"],"answer":0,"why":"La PK de una entidad débil es la PK del dueño (por la relación identificadora, el rombo doble POSEE) más su clave parcial. Id_Consulta sola se repite entre pacientes."},{"id":"0040-integrador-tp5-clinica#2","lesson":"0040-integrador-tp5-clinica","block":"sql","q":"¿Dónde se guarda F_DESDE, la fecha en que el paciente empieza a ocupar la habitación?","options":["En la tabla nueva OCUPACION","En la tabla de la HABITACION","En la tabla del mismo PACIENTE"],"answer":0,"why":"En OCUPACION. Es un atributo del rombo OCUPA, que es N:N, así que vive en la tabla que se crea para la relación. No es del paciente ni de la habitación: es del par."},{"id":"0040-integrador-tp5-clinica#3","lesson":"0040-integrador-tp5-clinica","block":"sql","q":"¿Por qué EDAD no es una columna de PACIENTE?","options":["Se deriva de la de nacimiento","La consigna no pide la edad","Es un atributo multivaluado"],"answer":0,"why":"Es un atributo derivado (óvalo punteado): se calcula a partir de F_Nacimiento. Guardarlo crea un dato que se desactualiza solo, cada año. Se calcula en la vista."},{"id":"0041-transacciones-y-acid#1","lesson":"0041-transacciones-y-acid","block":"fis","q":"\"O se ejecuta en su totalidad o no se ejecuta en absoluto.\" ¿Qué propiedad es?","options":["Atomicidad","Aislamiento","Durabilidad"],"answer":0,"why":"Atomicidad: la transacción es una unidad atómica de procesamiento. El todo o nada es su firma. Si falla en el medio, se deshace lo hecho hasta ahí."},{"id":"0041-transacciones-y-acid#2","lesson":"0041-transacciones-y-acid","block":"fis","q":"Dos transacciones corren al mismo tiempo y una lee datos que la otra está modificando. ¿Qué propiedad se está violando?","options":["El aislamiento de las transacciones","La consistencia de la base de datos","La durabilidad de los datos guardados"],"answer":0,"why":"Aislamiento. La palabra clave de su definición es simultánea: la ejecución de una transacción no debe interferir con ninguna otra transacción simultánea. Acá una se enteró de lo que hacía la otra."},{"id":"0041-transacciones-y-acid#3","lesson":"0041-transacciones-y-acid","block":"fis","q":"Una transacción ejecuta únicamente sentencias que recuperan datos. ¿Qué se puede decir?","options":["Es una transacción de sólo lectura","No llega a ser una transacción","No necesita cumplir con ACID"],"answer":0,"why":"Es una transacción de sólo lectura. El material incluye la recuperación entre las operaciones de acceso, así que consultar también forma una transacción: simplemente no actualiza la base."},{"id":"0049-oltp-olap-y-data-warehouse#1","lesson":"0049-oltp-olap-y-data-warehouse","block":"dw","q":"Un banco procesa miles de retiros y depósitos por segundo, con respuesta en milisegundos, las 24 horas. ¿Qué tipo de sistema es?","options":["Un sistema OLTP, transaccional","Un sistema OLAP, analítico","Un data mart departamental"],"answer":0,"why":"OLTP: procesa una gran cantidad de transacciones simples (inserciones, actualizaciones, eliminaciones), con respuesta en milisegundos y disponibilidad 24/7."},{"id":"0049-oltp-olap-y-data-warehouse#2","lesson":"0049-oltp-olap-y-data-warehouse","block":"dw","q":"¿Cuál de estas NO figura entre las características del Data Warehouse del deck?","options":["Volátil: sus datos se reescriben","Orientado a temas","Variante en el tiempo"],"answer":0,"why":"Volátil es lo opuesto: el DW es no volátil / histórico. Los datos se cargan y se conservan; no se pisan como en una base operativa."},{"id":"0049-oltp-olap-y-data-warehouse#3","lesson":"0049-oltp-olap-y-data-warehouse","block":"dw","q":"¿Qué es un cubo OLAP, según el deck?","options":["Información pre-agregada con todas las combinaciones de perspectivas","Un registro detallado de cada transacción diaria","Una tabla normalizada en tercera forma"],"answer":0,"why":"Información pre-agregada con todas las combinaciones posibles de las perspectivas, para visualizar las métricas que interesan al usuario."},{"id":"0049-oltp-olap-y-data-warehouse#4","lesson":"0049-oltp-olap-y-data-warehouse","block":"dw","q":"Un sistema guarda datos detallados en tablas normalizadas de una base relacional, sobre un esquema estrella. ¿Cuál es?","options":["ROLAP","MOLAP","HOLAP"],"answer":0,"why":"ROLAP: datos en una base relacional, detallados, sin agregaciones y normalizados; los esquemas típicos son estrella o copo de nieve."},{"id":"0049-oltp-olap-y-data-warehouse#5","lesson":"0049-oltp-olap-y-data-warehouse","block":"dw","q":"Un MOLAP ofrece un mayor desempeño en las consultas. ¿Qué desventaja tiene frente al ROLAP?","options":["Tamaño limitado para la arquitectura del cubo","Consultas más lentas","Construcción cara"],"answer":0,"why":"El tamaño del cubo es limitado, y los datos que están dentro no se pueden acceder directamente. Es el precio del precálculo."},{"id":"0050-componentes-de-un-dw#1","lesson":"0050-componentes-de-un-dw","block":"dw","q":"Un área lógica provisional donde los datos se borran, se arreglan por redundancia y se revisan contra las reglas del negocio antes de entrar al almacén. ¿Qué es?","options":["El ODS","El MDM","El cubo OLAP"],"answer":0,"why":"El ODS, almacén operacional de datos: el área provisional previa al DW, donde se limpian y revisan los datos."},{"id":"0050-componentes-de-un-dw#2","lesson":"0050-componentes-de-un-dw","block":"dw","q":"Un repositorio departamental, de visión parcial, de corta vida y orientado al proyecto. ¿Qué es?","options":["Un Data Mart","Un Data Warehouse","Un sistema OLTP"],"answer":0,"why":"Data Mart: departamental, visión parcial, restrictivo, corta vida / táctico y orientado al proyecto."},{"id":"0050-componentes-de-un-dw#3","lesson":"0050-componentes-de-un-dw","block":"dw","q":"Entre DW y Data Mart, ¿cuál está fuertemente desnormalizado?","options":["El Data Mart","El Data Warehouse","Ninguno: los dos están normalizados"],"answer":0,"why":"El Data Mart está fuertemente desnormalizado y sumarizado. El DW es suavemente desnormalizado y más detallado."},{"id":"0050-componentes-de-un-dw#4","lesson":"0050-componentes-de-un-dw","block":"dw","q":"En los componentes genéricos del DW, ¿qué etapa va inmediatamente después del almacén de datos?","options":["Los modelos analíticos","La limpieza y homogeneización","La recopilación de fuentes"],"answer":0,"why":"Los modelos analíticos: data marts y cubos OLAP, alimentados desde el DW, antes de la presentación."},{"id":"0051-modelo-estrella-y-copo-de-nieve#1","lesson":"0051-modelo-estrella-y-copo-de-nieve","block":"dw","q":"En un esquema en estrella, ¿cómo es la clave primaria de la tabla de hechos?","options":["Compuesta por las claves de las dimensiones","Un número correlativo propio del hecho","Simple, igual que la de las dimensiones"],"answer":0,"why":"Compuesta por las claves primarias de las tablas de dimensiones. Cada una es además foránea hacia su dimensión."},{"id":"0051-modelo-estrella-y-copo-de-nieve#2","lesson":"0051-modelo-estrella-y-copo-de-nieve","block":"dw","q":"El copo de nieve ahorra espacio al normalizar las dimensiones. ¿Qué cuesta a cambio?","options":["Más JOINs y peor rendimiento de consulta","Más redundancia de datos","Pierde la tabla de hechos"],"answer":0,"why":"Peor rendimiento: hay más tablas de dimensiones y más relaciones, así que cada consulta necesita más JOINs."},{"id":"0051-modelo-estrella-y-copo-de-nieve#3","lesson":"0051-modelo-estrella-y-copo-de-nieve","block":"dw","q":"Una metodología arranca con un almacén de datos global y normalizado, del que se nutren los data marts. ¿De quién es?","options":["Inmon, top-down","Kimball, bottom-up","Codd, relacional"],"answer":0,"why":"Inmon: top-down, un repositorio central único normalizado en tres formas normales; los Data Marts salen de ahí."},{"id":"0051-modelo-estrella-y-copo-de-nieve#4","lesson":"0051-modelo-estrella-y-copo-de-nieve","block":"dw","q":"Una empresa quiere una visión global y cuidar especialmente la integridad de los datos. ¿Qué enfoque conviene según el deck?","options":["El de Inmon","El de Kimball","Cualquiera: es indistinto"],"answer":0,"why":"Inmon: toda la empresa comparte la misma estructura normalizada, y eso protege la integridad entre departamentos."},{"id":"0052-slow-change-dimension#1","lesson":"0052-slow-change-dimension","block":"dw","q":"Para saber en qué estado estaba un cliente el 01/04/2023, ¿qué condición usás?","options":["La fecha pedida BETWEEN Fecha_Inicio AND Fecha_Fin","Fecha_Fin igual a la fecha 2100-12-31","Fecha_Inicio igual a la fecha pedida"],"answer":0,"why":"La fecha tiene que caer dentro del período de una foto: '2023-04-01' BETWEEN Fecha_Inicio AND Fecha_Fin. Como los períodos no se pisan, una sola foto cumple."},{"id":"0052-slow-change-dimension#2","lesson":"0052-slow-change-dimension","block":"dw","q":"Una foto vigente cambia el 2023-05-01. ¿Qué Fecha_Fin le queda a la foto vieja?","options":["2023-04-30, un día antes del inicio nuevo","2023-05-01, el mismo día del inicio nuevo","2100-12-31, la fecha de fin abierta"],"answer":0,"why":"2023-04-30: la Fecha_Inicio de la fila nueva menos un día. Así los períodos son consecutivos y no se pisan."},{"id":"0052-slow-change-dimension#3","lesson":"0052-slow-change-dimension","block":"dw","q":"Una estrategia de SCD agrega una fila nueva por cada cambio y guarda historia ilimitada. ¿Cuál es?","options":["SCD tipo 2: añadir fila","SCD tipo 1: sobrescribir","SCD tipo 3: añadir columna"],"answer":0,"why":"Tipo 2, añadir fila. Requiere columnas de inicio y fin, y es la que desarrolla el deck y la que se pide en la práctica."},{"id":"0052-slow-change-dimension#4","lesson":"0052-slow-change-dimension","block":"dw","q":"¿Por qué \"siempre una sola foto cumple\" lo pedido en la consulta de estado a una fecha?","options":["Los períodos de las fotos no se solapan","La clave del cliente es única en la tabla","El operador BETWEEN devuelve una sola fila"],"answer":0,"why":"Cada foto termina un día antes de que empiece la siguiente, así que los períodos no se solapan y cualquier fecha cae en uno solo."},{"id":"0052-slow-change-dimension#5","lesson":"0052-slow-change-dimension","block":"dw","q":"\"Calculá el promedio del saldo histórico de cada cliente.\" ¿Qué filas entran a la consulta?","options":["Todas las fotos de cada cliente, sin filtro de fechas","Sólo la foto vigente, con Fecha_Fin igual a 2100-12-31","La foto que cubre una fecha, con BETWEEN inicio y fin"],"answer":0,"why":"Todas las fotos, sin filtro de fechas, con GROUP BY cliente. La palabra histórico pide toda la historia; la vigente ya está incluida."},{"id":"0052-slow-change-dimension#6","lesson":"0052-slow-change-dimension","block":"dw","q":"Para la suma de todo el historial de saldos, ¿hay que agregar aparte la última foto?","options":["No, la historia ya incluye la foto vigente","Sí, hay que sumarla con una segunda consulta","Sí, a través de la vista actual del cliente"],"answer":0,"why":"No: la tabla histórica ya contiene la foto vigente. Sumarla aparte la contaría dos veces."},{"id":"0053-repaso-unidad-9#1","lesson":"0053-repaso-unidad-9","block":"dw","q":"Un repositorio corporativo, centralizado, que cruza toda la empresa y ofrece una visión homogénea. ¿Qué es?","options":["Un Data Warehouse, de alcance corporativo","Un Data Mart, de alcance departamental","Un cubo OLAP, de alcance multidimensional"],"answer":0,"why":"Es el DW: corporativo, neutral a las aplicaciones y compartido por toda la empresa. El Data Mart es departamental y de visión parcial."},{"id":"0053-repaso-unidad-9#2","lesson":"0053-repaso-unidad-9","block":"dw","q":"¿Cuál es la relación entre un Data Warehouse y OLAP?","options":["OLAP analiza datos que vienen de un data mart o de un DW","Son dos nombres distintos para el mismo repositorio de datos","OLAP es el sistema que alimenta al DW con las transacciones"],"answer":0,"why":"OLAP es el procesamiento analítico; sus datos provienen de un data mart, un almacén centralizado o un data warehouse. No son lo mismo: uno guarda, el otro analiza."},{"id":"0053-repaso-unidad-9#3","lesson":"0053-repaso-unidad-9","block":"dw","q":"¿Cuál define a OLAP?","options":["Análisis multidimensional de grandes volúmenes de datos, a alta velocidad","Procesamiento de muchas transacciones simples y simultáneas, en milisegundos","Conjunto de reglas que aseguran un mínimo de calidad de los datos recibidos"],"answer":0,"why":"Esa es la definición del deck. Su núcleo es el cubo y sirve para informes complejos, tendencias y previsiones."},{"id":"0053-repaso-unidad-9#4","lesson":"0053-repaso-unidad-9","block":"dw","q":"Según el deck, ¿qué es la inteligencia de negocios (BI)?","options":["Una arquitectura y aplicaciones sobre datos integrados, que se construye","Un producto de software que se compra ya armado a un proveedor externo","Una base de datos especializada, optimizada sólo para generar reportes"],"answer":0,"why":"El deck lo dice así: BI no se compra, se construye. Se vincula a una arquitectura y a aplicaciones para la toma de decisión."},{"id":"0053-repaso-unidad-9#5","lesson":"0053-repaso-unidad-9","block":"dw","q":"¿En qué se diferencia el ODS de un Data Warehouse?","options":["El ODS es un área provisional donde se limpian los datos antes de cargarlos","El ODS guarda toda la historia y el DW sólo conserva los datos del día","El ODS es un cubo multidimensional y el DW una tabla de hechos aislada"],"answer":0,"why":"El ODS es un área lógica provisional: ahí los datos se borran, se arreglan y se revisan. El DW es el repositorio histórico y no volátil."},{"id":"0053-repaso-unidad-9#6","lesson":"0053-repaso-unidad-9","block":"dw","q":"Un conjunto de procesos, políticas y tecnologías para gestionar los datos de las entidades de negocio centrales. ¿Qué es?","options":["MDM, gestión de datos maestros de las entidades de negocio centrales","DQ, reglas que aseguran un mínimo de calidad de los datos recibidos","ETL, proceso que extrae, transforma y carga los datos hacia el almacén"],"answer":0,"why":"Eso es MDM: gestiona, genera y mantiene los datos asociados a las entidades centrales del negocio."},{"id":"0053-repaso-unidad-9#7","lesson":"0053-repaso-unidad-9","block":"dw","q":"¿Qué significan las siglas ETL?","options":["Extracción, Transformación y Carga","Estructura, Tabla y Lectura de datos","Evaluación, Transacción y Log de datos"],"answer":0,"why":"Es el proceso que lleva los datos de las fuentes al Data Warehouse, con limpieza, integración y depuración en el medio."},{"id":"0053-repaso-unidad-9#8","lesson":"0053-repaso-unidad-9","block":"dw","q":"¿Qué hay en el centro de un esquema en estrella?","options":["La tabla de hechos, rodeada de varias tablas de dimensiones","Una tabla de dimensión, rodeada de varias tablas de hechos","Un cubo OLAP que guarda todas las agregaciones precalculadas"],"answer":0,"why":"La tabla de hechos va en el centro, y a su alrededor las dimensiones; por eso se llama estrella."},{"id":"0053-repaso-unidad-9#9","lesson":"0053-repaso-unidad-9","block":"dw","q":"Un esquema que normaliza las dimensiones para ahorrar espacio, a costa de más JOINs. ¿Cuál es?","options":["El esquema copo de nieve","El esquema en estrella","El esquema de cubo MOLAP"],"answer":0,"why":"Es la extensión de la estrella que agrega dimensiones normalizadas: menos redundancia, peor rendimiento."},{"id":"0053-repaso-unidad-9#10","lesson":"0053-repaso-unidad-9","block":"dw","q":"¿Qué diferencia a MOLAP de ROLAP?","options":["MOLAP guarda los datos en una estructura multidimensional y ROLAP en una base relacional","MOLAP usa SQL sobre tablas relacionales y ROLAP guarda los datos en cubos precalculados","No hay diferencia de fondo: son dos nombres distintos para el mismo modelo de OLAP"],"answer":0,"why":"Esa es la diferencia central: dónde se guardan los datos. MOLAP precalcula los resúmenes; ROLAP trabaja sobre tablas."},{"id":"0053-repaso-unidad-9#11","lesson":"0053-repaso-unidad-9","block":"dw","q":"¿Qué diferencia a Inmon de Kimball en el modelo de datos?","options":["Inmon propone un DW normalizado y Kimball uno desnormalizado en estrella","Inmon propone un modelo desnormalizado y Kimball uno normalizado en 3FN","Los dos proponen el mismo modelo y sólo cambian el nombre de las tablas"],"answer":0,"why":"El deck lo resume así: Inmon apuesta por una estructura normalizada frente a la desnormalización de Kimball."},{"id":"0053-repaso-unidad-9#12","lesson":"0053-repaso-unidad-9","block":"dw","q":"¿A qué se refiere Slow Change Dimension?","options":["A los datos de las dimensiones, que cambian poco a poco y no son incrementales","A los hechos, que se agregan muy lentamente a la tabla central del esquema","A las consultas de estado que tardan mucho tiempo en devolver su resultado"],"answer":0,"why":"Es la definición del deck: ventas y pedidos crecen todos los días; la categoría de un cliente o producto cambia despacio."},{"id":"0053-repaso-unidad-9#13","lesson":"0053-repaso-unidad-9","block":"dw","q":"¿Qué diferencia a un SCD tipo 1 de uno tipo 2?","options":["El tipo 1 sobrescribe el valor y el tipo 2 agrega una fila por cada cambio","El tipo 1 agrega una fila por cada cambio y el tipo 2 sobrescribe el valor","El tipo 1 agrega una columna nueva y el tipo 2 una tabla de historia aparte"],"answer":0,"why":"El tipo 1 no guarda historia ni agrega filas; el tipo 2 la guarda con Fecha_Inicio y Fecha_Fin."},{"id":"0053-repaso-unidad-9#14","lesson":"0053-repaso-unidad-9","block":"dw","q":"Un software que centraliza todas las interacciones con los clientes para mejorar su satisfacción y retención. ¿Qué es?","options":["Un CRM","Un ERP","Un ODS"],"answer":0,"why":"El CRM centraliza las interacciones con clientes, partners y stakeholders. Su objetivo es la mejor experiencia de cliente."},{"id":"0053-repaso-unidad-9#15","lesson":"0053-repaso-unidad-9","block":"dw","q":"¿Cuál de estos NO es una característica de un sistema OLTP?","options":["Leer grandes volúmenes de datos para extraer tendencias de ventas","Responder a cada transacción con tiempos calculados en milisegundos","Permanecer disponible las 24 horas del día, los 7 días de la semana"],"answer":0,"why":"Eso es OLAP. El OLTP procesa transacciones simples, no análisis de grandes volúmenes."}];
